const INST = "https://invidious.f5.si";
const vids = {
  A: "DiItGE3eAyQ", B: "kJQP7kiw5Fk", C: "t_jHrUE5IOk", D: "TyHvyGVs42U",
  E: "IHNzOHi8sJs", F: "zEf423kYfqk", G: "FzG4uDgje3M", H: "MR5XSOdjKMA",
  I: "sGIm0-dQd8M", J: "_P7S2lKif-A",
};
const out = {};
for (const [k, id] of Object.entries(vids)) {
  try {
    const r = await fetch(`${INST}/api/v1/videos/${id}?fields=title,lengthSeconds,storyboards`, {headers: {"User-Agent": "Mozilla/5.0"}});
    const j = await r.json();
    const sbs = (j.storyboards || []).map(s => ({
      w: s.width, h: s.height, count: s.count, interval: s.interval,
      cols: s.storyboardWidth, rows: s.storyboardHeight, pages: s.storyboardCount,
      tpl: s.templateUrl
    }));
    out[k] = {title: j.title, len: j.lengthSeconds, sbs};
  } catch (e) { out[k] = {error: String(e).slice(0, 150)}; }
}
